  {id:'verge',     ico:'🌑',nm:'Verge Expedition',   rl:'Abyssal Verge pioneers'},
  {id:'unwoven',   ico:'〰',nm:'Unwoven Hand',       rl:'Null cult (outlawed)'},
  {id:'none',      ico:'·', nm:'Unaffiliated',       rl:'No faction allegiance'},
];

