      '<div class="rn">'+r.nm+'</div>'+
      '<div class="rtr">'+r.tr+'</div>'+
      '<div class="rst">'+r.st+'</div>'+
    '</div>';
  }).join('');
}

function pickRace(id){
  selRace=id;
  document.querySelectorAll('.rc').forEach(function(el){el.classList.toggle('sel',el.dataset.id===id);});
  var r=RACES.find(function(x){return x.id===id;});
