    '<div class="out-note">Character data sealed. Send this output in your next message — the Codex will render the profile card.</div>'+
    '</div></div>';
}

(function(){
  buildRaces();buildClasses();buildStats();buildFactions();
  document.getElementById('pool-n').textContent=rem();
  var raw=document.getElementById('aeonraw');
  if(raw&&raw.value.trim()){
    var dec=document.createElement('textarea');
