      if(d.faction){var f=FACTIONS.find(function(x){return x.nm===d.faction;});if(f)pickFac(f.id);}
      if(d.anchor)document.getElementById('fanc').value=d.anchor;
      if(d.thread)document.getElementById('fth').value=d.thread;
      if(d.erosion!=null)document.getElementById('fer').value=d.erosion;
      if(d.objective)document.getElementById('fobj').value=d.objective;
    }catch(e){}
  }
})();
</script>
